import math
import numpy as np
from scipy.optimize import least_squares

_PARAMS = None

def _z0(row, tau):
    if row.get('mem_conv') is not None:
        return float(row['mem_conv'])
    prefix = row.get('raw_prefix') or []
    if not prefix:
        return 0.52 * float(row['x_now'])
    z = 0.52 * float(prefix[0]['x'])
    t_prev = float(prefix[0]['t'])
    for item in prefix[1:]:
        t = float(item['t'])
        x = float(item['x'])
        dt = t - t_prev
        decay = math.exp(-dt / tau)
        # Exact exponential-kernel update for linearly interpolated x.
        x_prev = _x_prev
        slope = (x - x_prev) / dt if dt else 0.0
        z = decay * z + 0.52 * (x_prev * (1.0 - decay) + slope * (dt - tau * (1.0 - decay)))
        t_prev = t
        _x_prev = x
    return z

def _z_initial(row, tau):
    if row.get('mem_conv') is not None:
        return float(row['mem_conv'])
    prefix = row.get('raw_prefix') or []
    if not prefix:
        return 0.52 * float(row['x_now'])
    z = 0.52 * float(prefix[0]['x'])
    t_prev = float(prefix[0]['t'])
    x_prev = float(prefix[0]['x'])
    for item in prefix[1:]:
        t = float(item['t']); x = float(item['x']); dt = t - t_prev
        decay = math.exp(-dt / tau)
        slope = (x - x_prev) / dt if dt else 0.0
        z = decay*z + 0.52*(x_prev*(1.0-decay) + slope*(dt-tau*(1.0-decay)))
        t_prev, x_prev = t, x
    return z

def _simulate(row, p):
    a, b, c, tau = [float(v) for v in p]
    x = float(row['x_now']); z = _z_initial(row, tau)
    u = float(row['u_now']); H = float(row['H'])
    n = max(1, int(math.ceil(H / 0.004))); dt = H / n
    def f(xv, zv):
        return (-a*xv + b*zv + c*u, (0.52*xv-zv)/tau)
    for _ in range(n):
        k1x,k1z=f(x,z)
        k2x,k2z=f(x+0.5*dt*k1x,z+0.5*dt*k1z)
        k3x,k3z=f(x+0.5*dt*k2x,z+0.5*dt*k2z)
        k4x,k4z=f(x+dt*k3x,z+dt*k3z)
        x += dt*(k1x+2*k2x+2*k3x+k4x)/6.0
        z += dt*(k1z+2*k2z+2*k3z+k4z)/6.0
    return x

def fit(train_rows):
    global _PARAMS
    y = np.array([float(r['y']) for r in train_rows])
    def residual(p):
        return np.array([_simulate(r,p) for r in train_rows]) - y
    result = least_squares(residual, x0=np.array([0.8,0.25,0.7,0.12]), bounds=([0.001,-5.0,-5.0,0.005],[8.0,5.0,5.0,3.0]), max_nfev=3000)
    _PARAMS = result.x.copy()
    return _PARAMS

def predict(row):
    if _PARAMS is None:
        raise RuntimeError('Call fit(train_rows) before predict(row)')
    return float(_simulate(row, _PARAMS))
